// Trivial accessors (generated by tools/re/gen_accessors.py from exact instruction patterns): field / global getters,
// constants, setters. Each macro defines our function, registers it like any rewrite, and adds it to the per-file
// table that the generic diff test walks (random object, original vs ours: EAX / EDX / pops / st0 / object bytes).
#pragma once
#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

#include "diff.h"
#include "regs.h"
#include "rewrite.h"

namespace game::acc {

enum Kind { GET32, LEA, FLD, CONST, FLDG, GETG, SX8, ZX8, SX16, ZX16, SET32 };
struct Entry {
    const char* name;
    Kind kind;
    uint32_t off;  // field offset / global address / constant
    int nargs;     // stack arguments (ret N / 4)
    const void* entry;
    void** orig;
};
inline std::vector<Entry>& table() {
    static std::vector<Entry> t;
    return t;
}
struct Add {
    Add(const Entry& e) { table().push_back(e); }
};
template <class T> inline T& fld(void* p, uint32_t off) { return *reinterpret_cast<T*>(static_cast<uint8_t*>(p) + off); }

// object bytes: big enough for every field offset the patterns use (checked by the generator)
constexpr uint32_t kObj = 0x1000;

inline DiffResult run_test(const DiffCtx& ctx, const char* test, const void* anchor) {
    return run_diff(ctx, test, anchor, [](Rng& r) -> Case {
        const auto& t = table();
        const Entry& e = t[r.below(static_cast<uint32_t>(t.size()))];
        if (!*e.orig) return Ok();  // not hooked (too short for a hook jump with no padding after it): never runs
        std::vector<uint8_t> a(kObj), b;
        for (auto& x : a) x = static_cast<uint8_t>(r.below(4) == 0 ? 0 : r.next());
        b = a;
        uint32_t args[4];
        for (auto& x : args) x = r.next();
        std::string bad;
        if (e.kind == FLD || e.kind == FLDG) {  // typed call: the register caller would leave st0 on the x87 stack
            const uintptr_t fo = reinterpret_cast<uintptr_t>(*e.orig), fm = reinterpret_cast<uintptr_t>(e.entry);
            float x = 0, y = 0;
            switch (e.nargs) {
                case 0: x = game_fn<float(__thiscall*)(void*)>(fo)(a.data()); y = game_fn<float(__thiscall*)(void*)>(fm)(b.data()); break;
                case 1: x = game_fn<float(__thiscall*)(void*, uint32_t)>(fo)(a.data(), args[0]); y = game_fn<float(__thiscall*)(void*, uint32_t)>(fm)(b.data(), args[0]); break;
                case 2: x = game_fn<float(__thiscall*)(void*, uint32_t, uint32_t)>(fo)(a.data(), args[0], args[1]); y = game_fn<float(__thiscall*)(void*, uint32_t, uint32_t)>(fm)(b.data(), args[0], args[1]); break;
                default: x = game_fn<float(__thiscall*)(void*, uint32_t, uint32_t, uint32_t)>(fo)(a.data(), args[0], args[1], args[2]); y = game_fn<float(__thiscall*)(void*, uint32_t, uint32_t, uint32_t)>(fm)(b.data(), args[0], args[1], args[2]); break;
            }
            uint32_t ux, uy;
            std::memcpy(&ux, &x, 4);
            std::memcpy(&uy, &y, 4);
            if (ux != uy && !(x != x && y != y)) bad += " st0";
        } else {
            uint32_t argsb[4];
            std::memcpy(argsb, args, sizeof args);
            const RegOutThis ra = call_regs_this(*e.orig, a.data(), args, e.nargs);
            const RegOutThis rb = call_regs_this(e.entry, b.data(), argsb, e.nargs);
            const uintptr_t pa = reinterpret_cast<uintptr_t>(a.data()), pb = reinterpret_cast<uintptr_t>(b.data());
            const bool same_eax = e.kind == LEA ? (ra.eax - pa) == (rb.eax - pb) : ra.eax == rb.eax;
            if (!same_eax) bad += " eax";
            if (ra.popped != rb.popped) bad += " pops";
            if (ra.edx == kSentEDX && rb.edx != kSentEDX) bad += " edx";
        }
        if (a != b) bad += " memory";
        return bad.empty() ? Ok() : MismatchText(std::string(e.name) + ":" + bad);
    });
}

}  // namespace game::acc

// one accessor: our function + registration + test-table entry
#define NFSU2_ACC(addr, name, kind, off, nargs, body, rettype)                                                  \
    namespace {                                                                                                 \
    void* o_##name = nullptr;                                                                                   \
    rettype __cdecl name(void* s) { (void)s; body }                                                             \
    }                                                                                                           \
    NFSU2_REWRITE_THIS(addr, name, nargs, #kind " accessor", o_##name);                                         \
    static ::game::acc::Add g_acc_##name({#name, ::game::acc::kind, off, nargs, NFSU2_ENTRY(name), &o_##name})

#define ACC_GET32(a, n, off, na) NFSU2_ACC(a, n, GET32, off, na, return ::game::acc::fld<uint32_t>(s, off);, uint32_t)
#define ACC_LEA(a, n, off, na) NFSU2_ACC(a, n, LEA, off, na, return static_cast<uint32_t>(reinterpret_cast<uintptr_t>(s)) + (off);, uint32_t)
#define ACC_FLD(a, n, off, na) NFSU2_ACC(a, n, FLD, off, na, return ::game::acc::fld<float>(s, off);, float)
#define ACC_CONST(a, n, v, na) NFSU2_ACC(a, n, CONST, v, na, return (v);, uint32_t)
#define ACC_FLDG(a, n, g, na) NFSU2_ACC(a, n, FLDG, g, na, return *reinterpret_cast<const float*>(g);, float)
#define ACC_GETG(a, n, g, na) NFSU2_ACC(a, n, GETG, g, na, return *reinterpret_cast<const uint32_t*>(g);, uint32_t)
#define ACC_SX8(a, n, off, na) NFSU2_ACC(a, n, SX8, off, na, return static_cast<uint32_t>(static_cast<int32_t>(::game::acc::fld<int8_t>(s, off)));, uint32_t)
#define ACC_ZX8(a, n, off, na) NFSU2_ACC(a, n, ZX8, off, na, return ::game::acc::fld<uint8_t>(s, off);, uint32_t)
#define ACC_SX16(a, n, off, na) NFSU2_ACC(a, n, SX16, off, na, return static_cast<uint32_t>(static_cast<int32_t>(::game::acc::fld<int16_t>(s, off)));, uint32_t)
#define ACC_ZX16(a, n, off, na) NFSU2_ACC(a, n, ZX16, off, na, return ::game::acc::fld<uint16_t>(s, off);, uint32_t)
#define ACC_SET32(addr, name, off)                                                                              \
    namespace {                                                                                                 \
    void* o_##name = nullptr;                                                                                   \
    uint32_t __cdecl name(void* s, uint32_t v) {                                                                \
        ::game::acc::fld<uint32_t>(s, off) = v;                                                                 \
        return v;                                                                                               \
    }                                                                                                           \
    }                                                                                                           \
    NFSU2_REWRITE_THIS(addr, name, 1, "SET32 accessor", o_##name);                                              \
    static ::game::acc::Add g_acc_##name({#name, ::game::acc::SET32, off, 1, NFSU2_ENTRY(name), &o_##name})
